def cleanup(self):
    """Clean up temporary files and directories"""
    temp_dir = self.clips_dir / 'temp_tts'
    if temp_dir.exists():
        shutil.rmtree(temp_dir)

    def cleanup_synthetic_clips(self):
        """
        Delete all synthetic clips but preserve real recordings.
        Used when force mode is enabled to regenerate synthetic samples.
        """
        deleted_count = 0

        # Delete synthetic positive clips (prefixed with 'synth_')
        if self.positive_dir.exists():
            for clip_path in self.positive_dir.glob('synth_*.wav'):
                try:
                    clip_path.unlink()
                    deleted_count += 1
                except Exception as e:
                    logger.warning(f"Failed to delete {clip_path}: {e}")

        # Delete all negative clips (they're regenerated from datasets)
        # But preserve real negative recordings (prefixed with 'real_negative_')
        if self.negative_dir.exists():
            for clip_path in self.negative_dir.glob('*.wav'):
                # Skip real negative recordings
                if clip_path.name.startswith('real_negative_'):
                    continue
                try:
                    clip_path.unlink()
                    deleted_count += 1
                except Exception as e:
                    logger.warning(f"Failed to delete {clip_path}: {e}")

        # Delete adversarial negative clips
        adversarial_dir = self.clips_dir / 'adversarial_negative'
        if adversarial_dir.exists():
            for clip_path in adversarial_dir.glob('*.wav'):
                try:
                    clip_path.unlink()
                    deleted_count += 1
                except Exception as e:
                    logger.warning(f"Failed to delete {clip_path}: {e}")

        # Clean up augmented clips
        positive_aug_dir = self.clips_dir / 'positive_augmented'
        if positive_aug_dir.exists():
            shutil.rmtree(positive_aug_dir)
            positive_aug_dir.mkdir(exist_ok=True)

        if deleted_count > 0:
            console.print(f"[yellow]Deleted {deleted_count} synthetic clips (preserving real recordings)[/yellow]")

        return deleted_count

    def verify_clips(self) -> Dict[str, any]:
        """
        Verify generated clips

        Returns:
            Verification results
        """
        results = {
            'positive': {'valid': 0, 'invalid': 0, 'issues': []},
            'negative': {'valid': 0, 'invalid': 0, 'issues': []}
        }

        for clip_type, clip_dir in [('positive', self.positive_dir), ('negative', self.negative_dir)]:
            clips = list(clip_dir.glob('*.wav'))

            for clip_path in clips:
                try:
                    sample_rate, audio = wavfile.read(str(clip_path))

                    # Check sample rate
                    if sample_rate != self.sample_rate:
                        results[clip_type]['invalid'] += 1
                        results[clip_type]['issues'].append(
                            f"{clip_path.name}: Wrong sample rate ({sample_rate} Hz)"
                        )
                        continue

                    # Check duration
                    if len(audio) != self.target_samples:
                        results[clip_type]['invalid'] += 1
                        results[clip_type]['issues'].append(
                            f"{clip_path.name}: Wrong length ({len(audio)} samples)"
                        )
                        continue

                    # Check for silence
                    if np.max(np.abs(audio)) < 100:
                        results[clip_type]['invalid'] += 1
                        results[clip_type]['issues'].append(
                            f"{clip_path.name}: Too quiet or silent"
                        )
                        continue

                    results[clip_type]['valid'] += 1

                except Exception as e:
                    results[clip_type]['invalid'] += 1
                    results[clip_type]['issues'].append(f"{clip_path.name}: {e}")

        return results

def ensure_dirs() -> None:
    SHARED_DIR.mkdir(exist_ok=True)
    LOGS_DIR.mkdir(exist_ok=True)

def load_memory() -> dict:
    if MEMORY_FILE.exists():
        return json.loads(MEMORY_FILE.read_text(encoding="utf-8"))
    return {}

def create_fresh_memory(tasks: list[dict], project: str = "Yardis") -> dict:
    agents = {}
    for t in tasks:
        name = t["agent"]
        if name not in agents:
            agents[name] = {
                "status": "pending",
                "task": t["prompt"],
                "messages": [],
                "output": {},
                "round": 0,
            }
    return {
        "project": project,
        "round": 0,
        "agents": agents,
        "artifacts": {},
    }

def save_memory(mem: dict) -> None:
    MEMORY_FILE.write_text(
        json.dumps(mem, indent=2, ensure_ascii=False), encoding="utf-8"
    )

def watch_memory(interval: float = 3.0, notify: bool = False) -> None:
    """Observa memory.json y notifica cambios de estado en los agentes."""
    sys.stdout.reconfigure(line_buffering=True)
    known: dict[str, tuple[str, int]] = {}
    print(f"  👀 Observando {MEMORY_FILE.resolve()}", flush=True)
    print(f"  Presiona Ctrl+C para salir\n", flush=True)

    if notify and IS_WINDOWS:
        try:
            import winrt.windows.ui.notifications as notifications  # type: ignore
            from winrt.windows.data.xml.dom import XmlDocument  # type: ignore
            _toast = notifications.ToastNotificationManager.create_toast_notifier()
        except ImportError:
            notify = False
    else:
        notify = False

    def _notify(title: str, body: str) -> None:
        if not notify:
            return
        try:
            template = """<toast><visual><binding template="ToastText02">
            <text id="1">{title}</text>
            <text id="2">{body}</text>
            </binding></visual></toast>"""
            xdoc = XmlDocument()
            xdoc.load_xml(template.format(title=title, body=body))
            _toast.show(notifications.ToastNotification(xdoc))
        except Exception:
            pass

    try:
        while True:
            time.sleep(interval)
            if not MEMORY_FILE.exists():
                continue
            mem = json.loads(MEMORY_FILE.read_text(encoding="utf-8"))
            for name, data in mem.get("agents", {}).items():
                status = data.get("status", "pending")
                msgs = len(data.get("messages", []))
                prev_status, prev_msgs = known.get(name, ("", -1))
                if prev_msgs == -1:
                    known[name] = (status, msgs)
                    continue
                if status != prev_status or msgs != prev_msgs:
                    elapsed = ""
                    if msgs > 0:
                        last = data["messages"][-1]
                        if isinstance(last, dict):
                            body = last.get("body", "")
                            if "exit 0" in body or "completed" in body:
                                elapsed = body
                            ts = last.get("ts", "")
                            if not elapsed and ts:
                                elapsed = ts[-8:] if len(ts) >= 8 else ts
                    icon = {"running": "▶", "completed": "✅", "failed": "❌", "pending": "⏳"}
                    line = f"  {icon.get(status, '?')} {name}: {status}"
                    if elapsed:
                        line += f" ({elapsed})"
                    task = data.get("task", "")
                    if task and status in ("completed", "failed"):
                        line += f" — {task[:60]}"
                    files = data.get("output", {}).get("files", [])
                    if files:
                        line += f" → {', '.join(files)}"
                    print(line, flush=True)
                    _notify(f"Multiagent: {name}", f"{status}: {task[:80]}")
                    known[name] = (status, msgs)
    except KeyboardInterrupt:
        print("\n  👋 Observador detenido", flush=True)

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="OpenCode multi-agent orchestrator with shared memory"
    )
    parser.add_argument("file", nargs="?", help="JSON file with task list")
    parser.add_argument(
        "--pipe", action="store_true", help="Read task list from stdin"
    )
    parser.add_argument(
        "--parallel", type=int, default=2, help="Max agents to run simultaneously"
    )
    parser.add_argument("--agent", help="Single agent name (quick mode)")
    parser.add_argument("--prompt", help="Single agent prompt (quick mode)")
    parser.add_argument(
        "--detach", action="store_true",
        help="Lanzar en background y devolver el control inmediatamente"
    )
    parser.add_argument(
        "--watch", action="store_true",
        help="Observar memory.json y notificar cambios en vivo"
    )
    parser.add_argument(
        "--notify", action="store_true",
        help="Enviar notificación del sistema en cambios (Windows Toast)"
    )
    parser.add_argument(
        "--interval", type=float, default=3.0,
        help="Intervalo de polling en segundos (default: 3)"
    )
    return parser.parse_args()

def _pythonw() -> str:
    """Busca pythonw.exe (sin consola) en Windows, o usa sys.executable como fallback."""
    if not IS_WINDOWS:
        return sys.executable
    exe = Path(sys.executable)
    # Mismo directorio que python.exe → pythonw.exe
    alt = exe.with_name("pythonw.exe")
    if alt.exists():
        return str(alt)
    # Fallback: probar en PATH
    for p in os.environ.get("PATH", "").split(os.pathsep):
        candidate = Path(p) / "pythonw.exe"
        if candidate.exists():
            return str(candidate)
    return str(exe)  # fallback a python.exe (mostrará consola)

