def stop_detection(self):
    """Stop detection"""
    self.is_running = False

class Clasificador:
    def __init__(self):
        self.intenciones = INTENCIONES
        self.modelo = SentenceTransformer("paraphrase-multilingual-MiniLM-L12-v2")
        self.vectores = {
            k: self.modelo.encode(v, convert_to_tensor=True)
            for k, v in self.intenciones.items()
        }

    def clasificar(self, texto, umbral=0.7):
        vector = self.modelo.encode(texto, convert_to_tensor=True)
        mejor = "NO_RECONOCIDO"
        mejor_score = 0
        for intent, vecs in self.vectores.items():
            score = util.cos_sim(vector, vecs).max().item()
            if score > mejor_score:
                mejor_score = score
                mejor = intent
        return (
            (mejor, mejor_score)
            if mejor_score >= umbral
            else ("NO_RECONOCIDO", mejor_score)
        )

def clasificar(self, texto, umbral=0.7):
    vector = self.modelo.encode(texto, convert_to_tensor=True)
    mejor = "NO_RECONOCIDO"
    mejor_score = 0
    for intent, vecs in self.vectores.items():
        score = util.cos_sim(vector, vecs).max().item()
        if score > mejor_score:
            mejor_score = score
            mejor = intent
    return (
        (mejor, mejor_score)
        if mejor_score >= umbral
        else ("NO_RECONOCIDO", mejor_score)
    )

    def list_available_voices(self, language: Optional[str] = None) -> List[Dict]:
        """
        List available recommended voices

        Args:
            language: Optional language filter

        Returns:
            List of voice information dictionaries
        """
        if language:
            if language in self.RECOMMENDED_VOICES:
                return self.RECOMMENDED_VOICES[language]
            else:
                return []
        else:
            # Return all voices
            all_voices = []
            for lang_voices in self.RECOMMENDED_VOICES.values():
                all_voices.extend(lang_voices)
            return all_voices

@property
def total_samples(self) -> int:
    """Total number of samples"""
    return self.true_positives + self.true_negatives + self.false_positives + self.false_negatives

@property
def accuracy(self) -> float:
    """Overall accuracy"""
    if self.total_samples == 0:
        return 0.0
    return (self.true_positives + self.true_negatives) / self.total_samples

@property
def precision(self) -> float:
    """Precision (positive predictive value)"""
    denominator = self.true_positives + self.false_positives
    if denominator == 0:
        return 0.0
    return self.true_positives / denominator

@property
def recall(self) -> float:
    """Recall (sensitivity, true positive rate)"""
    denominator = self.true_positives + self.false_negatives
    if denominator == 0:
        return 0.0
    return self.true_positives / denominator

@property
def f1_score(self) -> float:
    """F1 score (harmonic mean of precision and recall)"""
    if self.precision + self.recall == 0:
        return 0.0
    return 2 * (self.precision * self.recall) / (self.precision + self.recall)

@property
def specificity(self) -> float:
    """Specificity (true negative rate)"""
    denominator = self.true_negatives + self.false_positives
    if denominator == 0:
        return 0.0
    return self.true_negatives / denominator

@property
def false_positive_rate(self) -> float:
    """False positive rate"""
    return 1.0 - self.specificity

@property
def false_negative_rate(self) -> float:
    """False negative rate"""
    return 1.0 - self.recall

    def get_score_distribution(self) -> Dict[str, List[float]]:
        """
        Get distribution of scores by class

        Returns:
            Dictionary with 'positive' and 'negative' score lists
        """
        positive_scores = []
        negative_scores = []

        for run in self.runs:
            if 'score' in run:
                if run['ground_truth']:
                    positive_scores.append(run['score'])
                else:
                    negative_scores.append(run['score'])

        return {
            'positive': positive_scores,
            'negative': negative_scores
        }

def to_dict(self) -> Dict[str, Any]:
    """Convert config to dictionary"""
    return asdict(self)

    def validate(self) -> tuple[bool, list[str]]:
        """
        Validate configuration

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
        issues = []

        # Check required fields
        if not self.wake_word:
            issues.append("Wake word is required")

        if not self.project_name:
            issues.append("Project name is required")

        # Check sample counts
        if self.target_samples < 100:
            issues.append("Target samples should be at least 100")

        if self.real_samples < 10:
            issues.append("Real samples should be at least 10")

        # Check training settings
        if self.max_steps < 1000:
            issues.append("Max steps should be at least 1000")

        if self.batch_size < 32:
            issues.append("Batch size should be at least 32")

        if self.learning_rate <= 0 or self.learning_rate > 1:
            issues.append("Learning rate should be between 0 and 1")

        # Check audio settings
        if self.sample_rate not in [8000, 16000, 22050, 44100]:
            issues.append("Sample rate should be 8000, 16000, 22050, or 44100")

        if self.clip_duration_ms is not None and (self.clip_duration_ms < 500 or self.clip_duration_ms > 3000):
            issues.append("Clip duration should be between 500 and 3000 ms")

        # Check augmentation settings
        if self.augmentation_probability < 0 or self.augmentation_probability > 1:
            issues.append("Augmentation probability should be between 0 and 1")

        # Check voice settings
        if len(self.voices) < self.min_voices:
            issues.append(f"At least {self.min_voices} voices required, found {len(self.voices)}")

        return len(issues) == 0, issues

    def update(self, **kwargs):
        """
        Update configuration parameters

        Args:
            **kwargs: Parameters to update
        """
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)
            else:
                logger.warning(f"Unknown config parameter: {key}")

    def get_synthetic_samples_per_voice(self) -> int:
        """
        Calculate synthetic samples per voice

        Returns:
            Number of samples to generate per voice
        """
        if not self.voices:
            return 0

        return self.synthetic_samples // len(self.voices)

    @classmethod
    def get_voice_list(cls) -> List[str]:
        """
        Get list of available voices

        Returns:
            List of voice names
        """
        return cls.AVAILABLE_VOICES.copy()

    def list_installed_voices(self) -> List[dict]:
        """
        List installed voice models

        Returns:
            List of voice model information dictionaries
        """
        voices = []

        for model_file in self.voices_dir.glob('**/*.onnx'):
            # Read config if available
            config_file = model_file.with_suffix('.onnx.json')
            config = {}

            if config_file.exists():
                try:
                    with open(config_file, 'r') as f:
                        config = json.load(f)
                except Exception as e:
                    logger.warning(f"Failed to read config {config_file}: {e}")

            voices.append({
                'name': model_file.stem,
                'path': model_file,
                'config': config,
                'language': config.get('language', {}).get('code', 'unknown'),
                'quality': config.get('audio', {}).get('quality', 'unknown'),
                'sample_rate': config.get('audio', {}).get('sample_rate', 22050)
            })

        return voices

    def get_default_device(self) -> Optional[dict]:
        """
        Get default input device

        Returns:
            Default input device info or None
        """
        try:
            device_idx = sd.default.device[0]
            if device_idx is None:
                return None

            device = sd.query_devices(device_idx)
            return {
                'index': device_idx,
                'name': device['name'],
                'channels': device['max_input_channels'],
                'sample_rate': device['default_samplerate']
            }
        except Exception as e:
            logger.error(f"Failed to get default device: {e}")
            return None

