    def record_until_stopped(
        self,
        device: Optional[int] = None,
        callback=None
    ) -> np.ndarray:
        """
        Record audio until stop() is called

        Args:
            device: Device index (None for default)
            callback: Optional callback function called periodically with audio chunk

        Returns:
            Recorded audio as numpy array
        """
        self._audio_data = []
        self.recording = True

        def audio_callback(indata, frames, time, status):
            if status:
                logger.warning(f"Audio callback status: {status}")

            if self.recording:
                self._audio_data.append(indata.copy())
                if callback:
                    callback(indata)

        try:
            with sd.InputStream(
                samplerate=self.sample_rate,
                channels=self.channels,
                dtype=self.dtype,
                device=device,
                callback=audio_callback
            ):
                while self.recording:
                    sd.sleep(100)

        except Exception as e:
            logger.error(f"Recording failed: {e}")
            raise RuntimeError(f"Failed to record audio: {e}")

        # Combine all chunks
        if self._audio_data:
            audio = np.concatenate(self._audio_data, axis=0)
            return audio.flatten()
        else:
            return np.array([], dtype=self.dtype)

def stop(self):
    """Stop recording"""
    self.recording = False

    def validate_file(self, file_path: Path) -> Dict[str, any]:
        """
        Validate audio file

        Args:
            file_path: Path to audio file

        Returns:
            Validation results dictionary
        """
        try:
            sample_rate, audio = wavfile.read(str(file_path))

            # Convert to mono if stereo
            if len(audio.shape) > 1:
                audio = audio.mean(axis=1)

            # Convert to int16 if needed
            if audio.dtype != np.int16:
                audio = (audio / np.max(np.abs(audio)) * 32767).astype(np.int16)

            return self.validate_audio(audio, sample_rate)

        except Exception as e:
            logger.error(f"Failed to validate file {file_path}: {e}")
            return {
                'valid': False,
                'issues': [f"Failed to read file: {e}"],
                'warnings': [],
                'metrics': {}
            }

    def download_required(self):
        """Download only required (critical) datasets"""
        console.print("\n[bold]Downloading required datasets...[/bold]\n")

        # ACAV100M Training Features
        if not self.acav100m.is_training_cached():
            try:
                train_path = self.acav100m.download_training_features(resume=True)
                self.cache.add_entry('acav100m_train', str(train_path))
                console.print("[green]✓ ACAV100M training features downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download ACAV100M training: {e}[/red]\n")
        else:
            console.print("[green]✓ ACAV100M training features already cached[/green]\n")

        # ACAV100M Validation Features
        if not self.acav100m.is_validation_cached():
            try:
                val_path = self.acav100m.download_validation_features(resume=True)
                self.cache.add_entry('acav100m_val', str(val_path))
                console.print("[green]✓ ACAV100M validation features downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download ACAV100M validation: {e}[/red]\n")
        else:
            console.print("[green]✓ ACAV100M validation features already cached[/green]\n")

    def download_optional(self):
        """Download optional (recommended + optional) datasets"""
        console.print("\n[bold]Downloading optional datasets...[/bold]\n")

        # MIT RIR
        if not self.rir.is_cached():
            try:
                self.rir.download_all()
                self.cache.add_entry('rir', str(self.rir.dest_dir))
                console.print("[green]✓ MIT RIR downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download MIT RIR: {e}[/red]\n")
        else:
            console.print("[green]✓ MIT RIR already cached[/green]\n")

        # FSD50K
        if not self.fsd50k.is_cached():
            try:
                self.fsd50k.download_all()
                self.cache.add_entry('fsd50k', str(self.fsd50k.dest_dir))
                console.print("[green]✓ FSD50K downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download FSD50K: {e}[/red]\n")
        else:
            console.print("[green]✓ FSD50K already cached[/green]\n")

        # LibriSpeech (speech negatives)
        if not self.librispeech.is_cached():
            try:
                self.librispeech.download_all(max_samples=5000)
                self.cache.add_entry('librispeech', str(self.librispeech.speech_dir))
                console.print("[green]✓ LibriSpeech downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download LibriSpeech: {e}[/red]\n")
        else:
            console.print("[green]✓ LibriSpeech already cached[/green]\n")

        # DiPCo (false positive rate testing)
        if not self.dipco.is_cached():
            try:
                self.dipco.download_all()
                self.cache.add_entry('dipco', str(self.dipco.dipco_dir))
                console.print("[green]✓ DiPCo downloaded[/green]\n")
            except Exception as e:
                console.print(f"[red]✗ Failed to download DiPCo: {e}[/red]\n")
        else:
            console.print("[green]✓ DiPCo already cached[/green]\n")

    def count_cached_files(self) -> int:
        """Count number of cached audio files"""
        if not self.dest_dir.exists():
            return 0

        count = 0
        # Check new structure
        for audio_dir in [self.dest_dir / 'dev', self.dest_dir / 'eval']:
            if audio_dir.exists():
                count += sum(1 for _ in audio_dir.glob('*.wav'))

        # Also check old structure for backwards compatibility
        if count == 0:
            for audio_dir in [self.dest_dir / 'FSD50K.dev_audio', self.dest_dir / 'FSD50K.eval_audio']:
                if audio_dir.exists():
                    count += sum(1 for _ in audio_dir.glob('*.wav'))

        return count

def texto_a_numero(texto):
    """Convierte 'treinta y cinco' → 35"""
    texto = texto.strip().lower()
    if texto in PALABRAS_A_NUMEROS:
        return PALABRAS_A_NUMEROS[texto]
    if " y " in texto:
        partes = texto.split(" y ")
        if partes[0] in PALABRAS_A_NUMEROS and partes[1] in PALABRAS_A_NUMEROS:
            return PALABRAS_A_NUMEROS[partes[0]] + PALABRAS_A_NUMEROS[partes[1]]
    return None

def ejecutar(self):
    self.texto = self.tts.transcripcion()
    if not self.texto:
        return
    intencion, _ = self.clasificacion.clasificar(self.texto)
    if intencion != "NO_RECONOCIDO":
        if intencion == "MUSICA":
            reproductor.play(self.texto)
            return "Entendido, reproduciendo música"
        if intencion == "PAUSA":
            reproductor.pause()
            return "Entendido, música pausada"
        if intencion == "REANUDAR":
            reproductor.resume()
            return "Entendido, reanudando música"
        if intencion == "SIGUIENTE":
            reproductor.next()
            return "Entendido, siguiente canción"
        if intencion == "ANTERIOR":
            reproductor.previously()
            return "Entendido, canción anterior"
        if intencion == "VOLUMEN":
            doc = nlp(self.texto)
            for token in doc.ents:
                if token.label_ == "CARDINAL":
                    valor = texto_a_numero(token.text)
                    reproductor.volumen(valor / 100)
            return "Entendido, ajusté el volumen"
    if self.primera_vez:
        self.primera_vez = False
        prompt = f"{SISTEMA} --- Usuario:{self.texto}"
        cmd = ["opencode.cmd", "run", prompt]
    else:
        cmd = ["opencode.cmd", "run", "--continue", self.texto]
    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    self.output = result.stdout
    if "0x0x0Polo0700" in self.output:
        seccion = self.output.split("|", 5)
        utilidad_script = seccion
        seccion = [seccion[0], seccion[1], seccion[4]]
        respuesta = self.confirma.clasificar(seccion)
        if respuesta != 1:
            return None
        if utilidad_script[1] == "crear":
            if utilidad_script[2] == "directorio":
                cmd = [
                    "mkdir",
                    f"{utilidad_script[1]}",
                    f"{utilidad_script[2]}",
                ]
            if utilidad_script[2] == "archivo":
                cmd = ["comando de crear archivo que no se xD"]
            subprocess.run(cmd)
            if utilidad_script[1] == "eliminar":
                cmd = ["mv", f"{utilidad_script[2]}", "papelera"]
                subprocess.run(cmd)
            if utilidad_script[1] == "modificar":
                if utilidad_script[2] == "directorio":
                    cmd = ["mkdir", f"{seccion[1]}", f"{seccion[2]}"]
                if utilidad_script[2] == "archivo":
                    if utilidad_script[3] == "nombre":
                        cmd = ["comando para cambiar nombre de archivo"]
                    elif utilidad_script[3] == "contenido":
                        cmd = ["comando de recrear el archivo que no se xD"]
                    subprocess.run(cmd)
            if utilidad_script[1] == "mover":
                cmd = ["mv", f"{utilidad_script[2]}", f"{utilidad_script[6]}"]
            subprocess.run(cmd)
    if "1x1x1Polo0700" in self.output:
        preguntas = []
        result = self.output.split("|")
        a = int(result[-1])
        while a != len(preguntas):
            resultres = self.output.split("|")
            resultres.pop(-1)
            resultres.pop(0)
            for pregunta in resultres:
                self.lec.say(pregunta)
                dato = self.tts.transcripcion()
                if not dato:
                    continue
                preguntas.append(dato)
        cmd = [
            "opencode.cmd",
            "run",
            "--continue",
            "Respuestas del usuario: " + str(preguntas),
        ]
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
        )
        preguntas = []
    self.historial.agregar(self.output, self.texto)
    return self.output

pub fn run() {
  tauri::Builder::default()
    .invoke_handler(tauri::generate_handler![ping, enviar_msg])
    .plugin(tauri_plugin_shell::init())
    .plugin(tauri_plugin_os::init())
    .setup(|app| {
      let ruta = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf();
      let python_path = {
        let venv      = ruta.join(".venv").join("Scripts").join("pythonw.exe");
        let venv_exe  = ruta.join(".venv").join("Scripts").join("python.exe");
        if venv.exists() { venv }
        else if venv_exe.exists() { venv_exe }
        else { Path::new("pythonw").to_path_buf() }
      };
      match Command::new(&python_path)
        .arg("-m")
        .arg("core.server")
        .current_dir(&ruta)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
      {
        Ok(mut child) => {
          let stdout = child.stdout.take();
          let stderr = child.stderr.take();
          tauri::async_runtime::spawn(async move {
            if let Some(out) = stdout {
              let reader = BufReader::new(out);
              for line in reader.lines() {
                if let Ok(texto) = line {
                  print!("{}", texto);
                  std::io::stdout().flush().ok();
                }
              }
            }
          });
          tauri::async_runtime::spawn(async move {
            if let Some(err) = stderr {
              let reader = BufReader::new(err);
              for line in reader.lines() {
                if let Ok(texto) = line {
                  eprint!("{}", texto);
                }
              }
            }
          });
        }
        Err(e) => {
          eprintln!("Error al lanzar Python: {:?}", e);
        }
      }

      if cfg!(debug_assertions) {
        app.handle().plugin(
          tauri_plugin_log::Builder::default()
            .level(log::LevelFilter::Info)
            .build(),
        )?;
      }
      let handle = app.handle().clone();
      tauri::async_runtime::spawn(async move {
        // tomar la conexion 
        let connect = loop { 
          match connection(handle.clone()).await{ 
            Ok(con) => break con,
            Err(e) => {
              eprint!("cannot connect {}, we are retrying",e);
              sleep(Duration::from_secs(1)).await;
            }
          }
        };
        let connect = Arc::new(Mutex::new(connect));
        handle.manage(connect.clone());

        loop {
          let mut c = connect.lock().await;
          c.get().await;
        }
      });
      Ok(())
      // darle un espacio
      // abrirla usando connection
      // -para abrir la connection ocupo llamar la funcion de connection
      // -despues ya es todo pq la funcion por si sola ya hace las conexiones y las guarda en el struct
    })
    .run(tauri::generate_context!())
    .expect("error while running tauri application");
}

struct Connect {
  escritura: WsSink, 
  lectura: WsStream,
  handle: tauri::AppHandle,
}

async fn connection(handle: tauri::AppHandle)->Result<Connect, String>{
  let connection = match connect_async("ws://localhost:8765").await{
    Ok((con,_res) ) => con,
    Err(e) => return Err(format!("cannot connec: {}",e)),
  };
  let (send, get) = connection.split();
  Ok(Connect{
    escritura: send, 
    lectura: get,
    handle: handle,
  })
}

fn ping() -> String {
  "pong".to_string()
}

async fn send(&mut self, msg:Message)-> Result<(), String>{
  self.escritura.send(msg).await.map_err(|e| format!("Error al enviar mensaje: {}", e))
}

async fn get(&mut self){
  while let Some(msg) = self.lectura.next().await{
    if let Ok(Message::Text(texto)) = msg {
      let texto_string = texto.to_string();
      if let Err(e) = self.handle.emit("message", texto_string){
        eprint!("Error al enviar mensaje: {}",e);
      }
    }
  }
}

async fn enviar_msg(estado: tauri::State<'_, Arc<Mutex<Connect>>>, msg: String) -> Result<(), String> {
  let mut envio = estado.lock().await;
  envio.send(Message::Text(msg.into())).await.map_err(|e| format!("Error al enviar mensaje: {}", e))?;
  Ok(())
}

struct SecYar{
  pickerp: String,
  user: String,
  saltk: Vec<u8>,
  pickers: String,
}

fn new(usuario: String) -> Self {
  Self {
    pickerp: String::new(),
    user: usuario,
    saltk: Vec::new(),
    pickers: String::new(),
  }
}

fn picker(&mut self, password: String, usuario: String ) -> Result<String, String> {
  self.pickerp = password.clone();
  self.user = usuario.clone();
  let salt = SaltString::generate(&mut OsRng);
  let argon2 = Argon2::default();
  let picker = argon2.hash_password(password.as_bytes(), &salt).map_err(|e| format!("Error al hashear: {}", e))?.to_string();
  println!("datos recibidos: {}", picker);
  Ok(picker)
}

fn checkpicker(&mut self, picker_almacenado: String) -> Result<bool, String> {
  let argon2 =Argon2::default();
  let picker = PasswordHash::new(&picker_almacenado).map_err(|e| format!("Error al leer hash: {}", e))?;
  self.pickers = picker_almacenado.clone();
  Ok(argon2.verify_password(self.pickerp.as_bytes(), &picker).is_ok())
}

fn generatepickerk(&mut self) -> Result<Vec<u8>, String>{
  let mut pickerk = vec![0u8; 32];
  OsRng.fill_bytes(&mut pickerk);
  self.saltk = pickerk.clone();
  Ok(pickerk)
}

fn generatepickern(&mut self) -> Result<[u8; 12], String>{
  let mut pickern= [0u8; 12];
  OsRng.fill_bytes(&mut pickern);
  Ok(pickern)
  }

fn ecppicker(&mut self) -> Result<Vec<u8>, String>{
  let pickern = self.generatepickern()?;
  let pickerno = GenericArray::from_slice(&pickern);
  let picker = &self.saltk[..];
  let pickerc = Aes256Gcm:: new_from_slice(picker).map_err(|e| format!("Error key: {}", e))?;
  let ecppicker = pickerc.encrypt(pickerno, self.pickerp.as_bytes()).map_err(|e| format!("Error Encrypt {}",e))?;
  let mut resultado= Vec::new();
  resultado.extend_from_slice(&pickern);
  resultado.extend_from_slice(&self.saltk);
  resultado.extend_from_slice(&ecppicker);
  Ok(resultado)
}

fn save(&mut self) -> Result<Vec<u8>, String>{
  let ruta=Path::new("config").join("users").join(&self.user).join("password");
  let data = self.ecppicker().map_err(|e|format!("Data not upload by {}",e))?;
  let mut file = File::create(&ruta).map_err(|e| format!("File not created by {}", e))?;
  file.write_all(&data).map_err(|e| format!("File couldn't be written {}", e))?;
  Ok(data)
}

